   p=np.array(p); out.append((len(p),p[:,1].mean(),p[:,0].mean(),p[:,1].ptp()+1,p[:,0].ptp()+1))
 return out
for typ in ['o','p']:
 vals=[]
 for t,a in enumerate(f):
